import backtrader as bt


class SwingEma200RetestStrategy(bt.Strategy):
    params = (
        ('ema_period', 200),
        ('sma_period', 60),
        ('position_fraction', 0.01),
        ('fallback_take_profit', 0.05),
        ('stop_loss', 0.30),
    )

    def __init__(self):
        self.ema = bt.indicators.ExponentialMovingAverage(
            self.data.close, period=self.p.ema_period
        )
        self.sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_period
        )
        self.order = None
        self.breakout_seen = False
        self.breakout_bar = None
        self.entry_price = None

    def next(self):
        if self.order:
            return

        if self.position:
            stop_price = self.entry_price * (1.0 - self.p.stop_loss)
            if len(self.sma) >= self.p.sma_period:
                take_profit_reached = self.data.high[0] >= self.sma[0]
            else:
                take_profit_reached = (
                    self.data.high[0]
                    >= self.entry_price * (1.0 + self.p.fallback_take_profit)
                )

            if self.data.low[0] <= stop_price or take_profit_reached:
                self.order = self.close()
            return

        crossed_top_to_bottom = (
            self.data.close[-1] > self.ema[-1]
            and self.data.close[0] <= self.ema[0]
        )
        if crossed_top_to_bottom:
            self.breakout_seen = True
            self.breakout_bar = len(self)
            return

        retest_and_support_confirmation = (
            self.breakout_seen
            and len(self) > self.breakout_bar
            and self.data.low[0] <= self.ema[0]
            and self.data.close[0] >= self.ema[0]
            and self.data.close[0] > self.data.open[0]
        )
        if retest_and_support_confirmation:
            size = (self.broker.getvalue() * self.p.position_fraction) / self.data.close[0]
            self.order = self.buy(size=size)
            self.breakout_seen = False
            self.breakout_bar = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.entry_price = order.executed.price
            else:
                self.entry_price = None
            self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.order = None
